// `init`: a wizard that asks the questions of the starter procedure (templates/README.md)
// one at a time, or takes the answers without asking, and writes the skeleton of a brain
// with the instruction for the agent that finishes the setup. The text comes from the
// templates read at run time; the views are generated by `index`.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";
import { runIndex } from "./index.ts";
import { BCP47, KEBAB, lint, severity } from "./lint.ts";
import { isRelativeTarget, splitFrontmatter } from "./markdown.ts";
import { dirOf, loadRepo, relLink, ROOT_INSTRUCTION_FILES, str } from "./repo.ts";

export const TEMPLATES_DIR = fileURLToPath(new URL("../../templates/", import.meta.url));
export const SETUP_FILE = "DOTBRAIN-SETUP.md";
export const CLAUDE_SETTINGS = ".claude/settings.json";
/** The version of the package init runs from, written into the hook so that it runs the same `lint`. */
export const PACKAGE_VERSION: string = JSON.parse(
    readFileSync(fileURLToPath(new URL("../../package.json", import.meta.url)), "utf8"),
).version;
const MANAGED_END = "<!-- END:dotbrain -->";

export class InitError extends Error {}

export type Answers = Record<string, string>;

export interface Question {
    key: string;
    prompt: string;
    /** Asked by the wizard; the others are only taken from options. */
    asked: boolean;
    choices?: string[];
    default: (root: string) => string | null;
    /** The reason the answer is not valid, or null. */
    check: (value: string) => string | null;
}

const singleLine = (what: string) => (v: string) =>
    v === "" ? `${what} must not be empty` : /[\r\n]/.test(v) ? `${what} must be one line` : null;

const oneOf = (choices: string[]) => (v: string) =>
    choices.includes(v) ? null : `answer one of: ${choices.join(", ")}`;

function today(): string {
    const d = new Date();
    const p = (n: number) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

function gitUserName(root: string): string | null {
    try {
        const name = execFileSync("git", ["-C", root, "config", "user.name"], {
            encoding: "utf8",
            stdio: ["ignore", "pipe", "ignore"],
        }).trim();
        return name === "" ? null : name;
    } catch {
        return null;
    }
}

export const QUESTIONS: Question[] = [
    {
        key: "name",
        prompt: "Name of the brain (kebab-case, usually the name of the repository)",
        asked: true,
        default: (root) => {
            const name = basename(resolve(root))
                .toLowerCase()
                .replace(/[^a-z0-9]+/g, "-")
                .replace(/^-+|-+$/g, "");
            return name === "" ? null : name;
        },
        check: (v) => (KEBAB.test(v) ? null : `"${v}" is not lowercase kebab-case (for example my-project)`),
    },
    {
        key: "lang",
        prompt: "Language of the brain (BCP 47 tag, for example en or pl)",
        asked: true,
        default: () => "en",
        check: (v) => (BCP47.test(v) ? null : `"${v}" is not a BCP 47 tag (for example en, pl or pt-BR)`),
    },
    {
        key: "owner",
        prompt: "Owner of the brain (a person or a role)",
        asked: true,
        default: gitUserName,
        check: singleLine("the owner"),
    },
    {
        key: "description",
        prompt: "One sentence describing the project",
        asked: true,
        default: () => null,
        check: singleLine("the description"),
    },
    {
        key: "languages",
        prompt: "Language of code, comments, commits, branch names and pull requests",
        asked: true,
        default: () => "English",
        check: singleLine("the language"),
    },
    {
        key: "order",
        prompt: "Order of work: changes to the brain in the same pull request as the work, or to the main branch in a separate pull request before it",
        asked: true,
        choices: ["with-the-work", "before-the-work"],
        default: () => "with-the-work",
        check: oneOf(["with-the-work", "before-the-work"]),
    },
    {
        key: "step-ids",
        prompt: "Are steps named by the keys of their tickets in the issue tracker instead of numbers",
        asked: true,
        choices: ["no", "yes"],
        default: () => "no",
        check: oneOf(["no", "yes"]),
    },
    {
        key: "date",
        prompt: "Date of the first decisions (YYYY-MM-DD)",
        asked: false,
        default: () => today(),
        check: (v) =>
            /^\d{4}-\d{2}-\d{2}$/.test(v) &&
            !Number.isNaN(Date.parse(`${v}T00:00:00Z`)) &&
            new Date(`${v}T00:00:00Z`).toISOString().startsWith(v)
                ? null
                : `"${v}" is not a date YYYY-MM-DD`,
    },
];

const QUESTION_KEYS = new Set(QUESTIONS.map((q) => q.key));

// ------------------------------------------------------------------ the skeleton

interface Plan {
    /** Files written by init, which must not exist yet. */
    created: Map<string, string>;
    decisions: string[];
}

function readTemplate(dir: string, name: string): string {
    const file = join(dir, name);
    if (!existsSync(file)) throw new InitError(`template ${name} not found in ${dir}`);
    return readFileSync(file, "utf8");
}

function fill(text: string, values: Record<string, string>): string {
    return text.replace(/<[^<>\n]+>/g, (m) => values[m] ?? m);
}

function yamlQuoted(value: string): string {
    return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function yamlScalar(value: string): string {
    return /^[A-Za-z0-9][A-Za-z0-9 ._@/-]*$/.test(value) && !value.endsWith(" ") ? value : `"${yamlQuoted(value)}"`;
}

function isEnglish(lang: string): boolean {
    return lang.split("-")[0]!.toLowerCase() === "en";
}

/** `.brain/README.md` from the index template: the manifest filled in, its comments removed, and the map removed for English. */
function brainReadme(template: string, a: Answers): string {
    const filled = fill(template, {
        "<brain-name>": a.name!,
        "<language-tag>": a.lang!,
        "<person-or-role>": yamlScalar(a.owner!),
        "<One sentence: what this brain is the source of truth for.>": yamlQuoted(a.description!),
        "<Project name>": a.name!,
    });
    const fm = splitFrontmatter(filled);
    if (!fm.present) throw new InitError("template index.md has no frontmatter");
    const head = filled.slice(0, filled.length - fm.body.length).split("\n");
    const out: string[] = [];
    let inSections = false;
    for (const line of head) {
        if (/^\s*#/.test(line)) continue;
        if (inSections && /^\s+\S/.test(line)) continue;
        inSections = false;
        if (line === "sections:" && isEnglish(a.lang!)) {
            inSections = true;
            continue;
        }
        out.push(line);
    }
    return out.join("\n") + fm.body;
}

function plan(a: Answers, templates: string): Plan {
    const created = new Map<string, string>();
    const date = a.date!;
    const decision = (slug: string, template: string, values: Record<string, string> = {}) => {
        const path = `.brain/decisions/process/${date}-${slug}.md`;
        created.set(path, fill(readTemplate(templates, template), { "<YYYY-MM-DD>": date, ...values }));
        return path;
    };
    created.set(".brain/README.md", brainReadme(readTemplate(templates, "index.md"), a));
    const decisions = [
        decision("languages", "languages.md", { "<language>": a.languages! }),
        decision("order-of-work", a.order === "before-the-work" ? "order-of-work-before.md" : "order-of-work.md"),
    ];
    if (a["step-ids"] === "yes") decisions.push(decision("step-ids", "step-ids.md"));
    created.set(".claude/agents/brain-review.md", readTemplate(templates, "brain-review.md"));
    return { created, decisions };
}

/** The part "Finishing the setup" of the procedure, with relative links reduced to their text, and the templates it links to. */
function finishingSteps(templates: string): { steps: string; linked: string[] } {
    const lines = readTemplate(templates, "README.md").split("\n");
    const start = lines.indexOf("## Finishing the setup");
    if (start === -1) throw new InitError('templates/README.md has no section "## Finishing the setup"');
    let end = lines.findIndex((l, i) => i > start && l.startsWith("## "));
    if (end === -1) end = lines.length;
    const linked: string[] = [];
    const unlink = (prose: string) =>
        prose.replace(/\[([^\]]*)\]\(([^()\s]+)\)/g, (link, text: string, target: string) => {
            if (!isRelativeTarget(target)) return link;
            const path = target.split("#")[0]!;
            if (
                !path.includes("/") &&
                path.endsWith(".md") &&
                existsSync(join(templates, path)) &&
                !linked.includes(path)
            )
                linked.push(path);
            return text;
        });
    // Code spans (between backticks) are kept as they are.
    const steps = lines
        .slice(start + 1, end)
        .join("\n")
        .trim()
        .split(/(`[^`]*`)/)
        .map((part, i) => (i % 2 === 1 ? part : unlink(part)))
        .join("");
    return { steps, linked };
}

/** `.claude/settings.json` from the template, with the version of the package in the hook. */
function claudeSettings(templates: string): string {
    const text = readTemplate(templates, "claude-settings.json").split("<version>").join(PACKAGE_VERSION);
    try {
        JSON.parse(text);
    } catch (e) {
        throw new InitError(`template claude-settings.json is not valid JSON: ${(e as Error).message}`);
    }
    return text;
}

/** The entries of `hooks.Stop` of the settings, for an agent adding them to an existing file. */
function stopEntries(settings: string): string {
    const stop = (JSON.parse(settings) as { hooks?: { Stop?: unknown[] } }).hooks?.Stop;
    if (!Array.isArray(stop) || stop.length === 0)
        throw new InitError("template claude-settings.json has no `hooks.Stop` entry");
    return stop.map((entry) => JSON.stringify(entry, null, 2)).join("\n");
}

function setupFile(templates: string, settings: string | null): { content: string; pointer: string; prompt: string } {
    const fm = splitFrontmatter(readTemplate(templates, "agent-setup.md"));
    const pointer = str(fm.data.pointer);
    const prompt = str(fm.data.prompt);
    const hook = str(fm.data.hook);
    if (!fm.present || fm.error || !pointer || !prompt || !hook)
        throw new InitError("template agent-setup.md needs `pointer`, `prompt` and `hook` in its frontmatter");
    const { steps, linked } = finishingSteps(templates);
    const appendix = linked
        .map(
            (name) => `### ${name}\n\n\`\`\`\`markdown\n${readTemplate(templates, name).replace(/\n*$/, "\n")}\`\`\`\``,
        )
        .join("\n\n");
    // Only when init did not write `.claude/settings.json`: the agent adds the hook to the existing file.
    const hookStep = settings === null ? "" : `\n${hook}\n\n\`\`\`json\n${stopEntries(settings)}\n\`\`\`\n`;
    const parts: Record<string, string> = { "<finishing-steps>": steps, "<templates>": appendix };
    const content = fm.body
        .replace(/^\n+/, "")
        .replace(/\n<claude-hook>\n/, () => `\n${hookStep}`)
        .replace(/<finishing-steps>|<templates>/g, (m) => parts[m]!)
        .replace(/\n*$/, "\n");
    return { content, pointer, prompt };
}

/** Inserts the line pointing to the setup file directly after the managed block, outside it. */
function withPointer(text: string, pointer: string): string {
    const lines = text.split("\n");
    const end = lines.indexOf(MANAGED_END);
    if (end === -1) throw new InitError("managed block not found after index");
    const insert = ["", pointer];
    if (lines[end + 1] !== undefined && lines[end + 1]!.trim() !== "") insert.push("");
    lines.splice(end + 1, 0, ...insert);
    return lines.join("\n");
}

function gitTop(root: string): void {
    let top: string;
    try {
        top = execFileSync("git", ["-C", root, "rev-parse", "--show-toplevel"], {
            encoding: "utf8",
            stdio: ["ignore", "pipe", "ignore"],
        }).trim();
    } catch {
        throw new InitError(`${root} is not a git repository; dotbrain sets up a brain in a code repository`);
    }
    if (realpathSync(top) !== realpathSync(root))
        throw new InitError(`${root} is not the top of its git repository (${top})`);
}

/** Checks that need no answers: a git repository without a brain. */
export function preflight(root: string): void {
    if (!existsSync(root)) throw new InitError(`${root} does not exist`);
    gitTop(root);
    if (existsSync(join(root, ".brain/README.md")))
        throw new InitError("the repository already has a brain (.brain/README.md); init changes nothing");
}

function ignored(root: string, path: string): boolean {
    try {
        execFileSync("git", ["-C", root, "check-ignore", "-q", "--no-index", path], { stdio: "ignore" });
        return true;
    } catch {
        return false;
    }
}

export interface ScaffoldResult {
    written: string[];
    warnings: string[];
    notes: string[];
    prompt: string;
}

/** Writes the skeleton from complete, valid answers. Changes nothing when a check fails. */
export function scaffold(root: string, answers: Answers, templates = TEMPLATES_DIR): ScaffoldResult {
    for (const q of QUESTIONS) {
        const v = answers[q.key];
        if (v === undefined) throw new InitError(`no answer for ${q.key}`);
        const reason = q.check(v);
        if (reason) throw new InitError(`${q.key}: ${reason}`);
    }
    preflight(root);
    const p = plan(answers, templates);
    const settings = claudeSettings(templates);
    // An existing `.claude/settings.json` is the repository's own: init leaves it and tells the agent to add the hook.
    const settingsExist = existsSync(join(root, CLAUDE_SETTINGS));
    if (!settingsExist) p.created.set(CLAUDE_SETTINGS, settings);
    const setup = setupFile(templates, settingsExist ? settings : null);
    p.created.set(SETUP_FILE, setup.content);
    for (const path of p.created.keys()) {
        if (existsSync(join(root, path))) throw new InitError(`${path} already exists; init overwrites nothing`);
    }
    for (const file of ROOT_INSTRUCTION_FILES) {
        const full = join(root, file);
        if (existsSync(full) && readFileSync(full, "utf8").split("\n").includes(MANAGED_END))
            throw new InitError(`${file} already has a managed block; init overwrites nothing`);
    }

    const written = new Set<string>();
    const write = (path: string, content: string) => {
        mkdirSync(dirname(join(root, path)), { recursive: true });
        writeFileSync(join(root, path), content);
        written.add(path);
    };
    for (const [path, content] of p.created) if (path !== SETUP_FILE) write(path, content);
    for (const file of ROOT_INSTRUCTION_FILES) {
        if (!existsSync(join(root, file))) write(file, `# ${answers.name}\n`);
    }
    const index = runIndex(root, { check: false });
    if (index.skipped.length) throw new InitError(`the views were not generated: ${index.skipped.join("; ")}`);
    for (const path of index.changed) written.add(path);
    write(SETUP_FILE, setup.content);
    for (const file of ROOT_INSTRUCTION_FILES) {
        const pointer = fill(setup.pointer, { "<setup-file>": relLink(dirOf(file), SETUP_FILE) });
        write(file, withPointer(readFileSync(join(root, file), "utf8"), pointer));
    }

    const warnings = [".claude/rules/", ".claude/agents/"]
        .filter((d) => ignored(root, `${d}x.md`))
        .map(
            (d) =>
                `git ignores ${d}; commit it anyway (git add -f) or change .gitignore, so that the team gets ${d === ".claude/rules/" ? "the rules with a glob" : "the review subagent"}`,
        );
    return { written: [...written].sort(), warnings, notes: index.notes, prompt: setup.prompt };
}

// ------------------------------------------------------------------ command line

const USAGE = `Usage: dotbrain init [<repository>] [--answers <file.json>] [--<question>=<answer>...] [--yes]
Questions: ${QUESTIONS.map((q) => q.key).join(", ")}`;

interface Parsed {
    root: string;
    answers: Answers;
    yes: boolean;
}

function parseArgs(args: string[]): Parsed {
    let root: string | null = null;
    let file: string | null = null;
    let yes = false;
    const given: Answers = {};
    for (let i = 0; i < args.length; i++) {
        const arg = args[i]!;
        if (!arg.startsWith("--")) {
            if (root !== null) throw new InitError(USAGE);
            root = arg;
            continue;
        }
        const eq = arg.indexOf("=");
        const key = eq === -1 ? arg.slice(2) : arg.slice(2, eq);
        if (key === "yes" && eq === -1) {
            yes = true;
            continue;
        }
        const value = eq === -1 ? args[++i] : arg.slice(eq + 1);
        if (value === undefined) throw new InitError(`--${key} needs a value\n${USAGE}`);
        if (key === "answers") file = value;
        else if (QUESTION_KEYS.has(key)) given[key] = value.trim();
        else throw new InitError(`unknown option --${key}\n${USAGE}`);
    }
    const answers: Answers = {};
    if (file !== null) {
        let data: unknown;
        try {
            data = JSON.parse(readFileSync(file, "utf8"));
        } catch (e) {
            throw new InitError(`cannot read the answers file ${file}: ${(e as Error).message}`);
        }
        if (typeof data !== "object" || data === null || Array.isArray(data))
            throw new InitError(`${file}: the answers must be a JSON object`);
        for (const [k, v] of Object.entries(data)) {
            if (!QUESTION_KEYS.has(k)) throw new InitError(`${file}: unknown question "${k}"`);
            if (typeof v !== "string") throw new InitError(`${file}: the answer to "${k}" must be a string`);
            answers[k] = v.trim();
        }
    }
    Object.assign(answers, given);
    for (const [k, v] of Object.entries(answers)) {
        const reason = QUESTIONS.find((q) => q.key === k)!.check(v);
        if (reason) throw new InitError(`${k}: ${reason}`);
    }
    return { root: resolve(root ?? "."), answers, yes };
}

/** Reads lines of standard input one at a time, buffering lines that arrive before they are asked for. */
function lineReader() {
    const rl = createInterface({ input: process.stdin, terminal: false });
    const it = rl[Symbol.asyncIterator]();
    return {
        ask: async (prompt: string): Promise<string | null> => {
            process.stdout.write(prompt);
            const r = await it.next();
            if (r.done) return null;
            if (!process.stdin.isTTY) process.stdout.write("\n");
            return r.value;
        },
        close: () => rl.close(),
    };
}

export async function runInit(args: string[]): Promise<number> {
    let parsed: Parsed;
    try {
        parsed = parseArgs(args);
        preflight(parsed.root);
    } catch (e) {
        if (e instanceof InitError) {
            console.error(`error: ${e.message}`);
            return 2;
        }
        throw e;
    }
    const { root, answers, yes } = parsed;
    const missing = QUESTIONS.filter((q) => answers[q.key] === undefined);
    let asked = false;
    if (yes || missing.every((q) => !q.asked)) {
        for (const q of missing) {
            const d = q.default(root);
            if (d === null) {
                console.error(`error: no answer for ${q.key} and no default; give --${q.key}`);
                return 2;
            }
            answers[q.key] = d;
        }
    } else {
        const reader = lineReader();
        try {
            for (const q of QUESTIONS) {
                if (answers[q.key] !== undefined) continue;
                const d = q.default(root);
                if (!q.asked) {
                    if (d !== null) answers[q.key] = d;
                    continue;
                }
                asked = true;
                const choices = q.choices ? ` (${q.choices.join("/")})` : "";
                for (;;) {
                    const line = await reader.ask(`${q.prompt}${choices}${d !== null ? ` [${d}]` : ""}: `);
                    if (line === null) {
                        console.error("error: the input ended before every question was answered; nothing was written");
                        return 2;
                    }
                    const value = line.trim() === "" ? d : line.trim();
                    const reason = value === null ? "an answer is required" : q.check(value);
                    if (reason === null && value !== null) {
                        answers[q.key] = value;
                        break;
                    }
                    console.log(`  ${reason}`);
                }
            }
            if (asked) {
                console.log("\nSummary:");
                for (const q of QUESTIONS) console.log(`  ${q.key}: ${answers[q.key]}`);
                const confirm = await reader.ask("Write the brain? [Y/n]: ");
                if (confirm === null || !/^(y|yes|)$/i.test(confirm.trim())) {
                    console.log("Nothing was written.");
                    return 1;
                }
            }
        } finally {
            reader.close();
        }
    }

    let result: ScaffoldResult;
    try {
        result = scaffold(root, answers);
    } catch (e) {
        if (e instanceof InitError) {
            console.error(`error: ${e.message}`);
            return 2;
        }
        throw e;
    }
    for (const p of result.written) console.log(`wrote ${p}`);
    for (const w of result.warnings) console.error(`warning: ${w}`);
    for (const n of result.notes) console.error(`note: ${n}`);
    const violations = lint(loadRepo(root)).violations;
    for (const v of violations) console.log(`${severity(v.rule)} ${v.rule} ${v.path}: ${v.message}`);
    const stale = runIndex(root, { check: true }).changed;
    for (const s of stale) console.log(`error V-VIEWS ${s}: out of date`);
    if (violations.some((v) => severity(v.rule) === "error") || stale.length) return 1;
    console.log(
        `\nThe skeleton of the brain is ready and valid. Open your AI agent in ${root} and tell it:\n\n  ${result.prompt}\n`,
    );
    return 0;
}
